/**
 * Registers the service worker generated by vite-plugin-pwa (production, browser only). Failure
 * never affects the app. It uses the plain browser API rather than `virtual:pwa-register`, which
 * would need the extra `workbox-window` dependency; with registerType 'autoUpdate' the generated
 * worker already skips waiting and claims clients, so updates apply on the next load.
 */
export function registerSw(): void {
  if (
    !import.meta.env.PROD ||
    typeof window === 'undefined' ||
    !('serviceWorker' in navigator)
  )
    return;
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(() => {
      /* offline install is a bonus; ignore */
    });
  });
}
